#pragma once

/// Known-answer vectors for the functional tests. The *.inc files next to this
/// header are generated by tools/gen_vectors.py from the vectors in
/// crates/crypto/src/testvectors; each one defines one array of the types
/// below in namespace vectors. Byte strings are hex; hex() decodes them.

#include <stdexcept>
#include <string_view>
#include <vector>

namespace vectors
{

/// A NIST AES known answer: key, IV (CBC) or 16-byte tweak (XTS), plaintext
/// and ciphertext.
struct AesVector
{
    const char *key;
    const char *iv;
    const char *pt;
    const char *ct;
};

/// An RSA key: the private key as PKCS#8 DER, and the modulus and public
/// exponent as CKA_MODULUS and CKA_PUBLIC_EXPONENT carry them.
struct RsaKey
{
    const char *pkcs8;
    const char *n;
    const char *e;
};

/// An RSA signature over msg: md is the hash (OpenSSL name), for PSS also the
/// MGF1 hash, with a salt as long as the hash.
struct RsaSigVector
{
    const char *md;
    const RsaKey *key;
    const char *msg;
    const char *sig;
};

/// An RSA-OAEP encryption of msg: md is the OAEP and the MGF1 hash, no label.
struct RsaOaepVector
{
    const char *md;
    const RsaKey *key;
    const char *msg;
    const char *ct;
};

/// An ECDH known answer: the peer's uncompressed point, the big-endian private
/// scalar and the shared x-coordinate.
struct EcdhVector
{
    const char *curve;
    const char *pub;
    const char *priv;
    const char *shared;
};

/// Decode a hex string (an odd length or a non-hex digit throws).
inline std::vector<unsigned char> hex(std::string_view s)
{
    auto nibble = [](char c) -> unsigned char {
        if ((c >= '0') && (c <= '9'))
        {
            return static_cast<unsigned char>(c - '0');
        }
        if ((c >= 'a') && (c <= 'f'))
        {
            return static_cast<unsigned char>(c - 'a' + 10);
        }
        if ((c >= 'A') && (c <= 'F'))
        {
            return static_cast<unsigned char>(c - 'A' + 10);
        }
        throw std::invalid_argument("hex: not a hex digit");
    };
    if ((s.size() % 2) != 0)
    {
        throw std::invalid_argument("hex: odd length");
    }
    std::vector<unsigned char> out(s.size() / 2);
    for (size_t i = 0; i < out.size(); i++)
    {
        out[i] = static_cast<unsigned char>((nibble(s[2 * i]) << 4) | nibble(s[(2 * i) + 1]));
    }
    return out;
}

} // namespace vectors
